messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Low Poly Treadmill Cycle</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #111; }
        canvas { display: block; }
    </style>
</head>
<body>
<script type="module">
    import * as THREE from './three.module.js';

    // --- Configuration ---
    const CYCLE_DURATION = 10; // 10 seconds total
    const PHASE_STILL = 2;
    const PHASE_WALK = 3;
    const PHASE_RUN = 3;

    // --- Setup ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x202025);
    scene.fog = new THREE.Fog(0x202025, 10, 50);

    const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
    camera.position.set(0, 2.5, 8); // Side-on view
    camera.lookAt(0, 1, 0);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    document.body.appendChild(renderer.domElement);

    // --- Lighting ---
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
    scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
    dirLight.position.set(5, 10, 5);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 1024;
    dirLight.shadow.mapSize.height = 1024;
    scene.add(dirLight);

    // --- Materials ---
    const skinMat = new THREE.MeshStandardMaterial({ color: 0x00ffcc, flatShading: true });
    const shirtMat = new THREE.MeshStandardMaterial({ color: 0xff3366, flatShading: true });
    const pantsMat = new THREE.MeshStandardMaterial({ color: 0x333333, flatShading: true });
    const shoeMat = new THREE.MeshStandardMaterial({ color: 0xffffff, flatShading: true });
    const beltMat = new THREE.MeshStandardMaterial({ color: 0x111111, flatShading: true });

    // --- Character Construction ---
    const characterGroup = new THREE.Group();
    scene.add(characterGroup);

    // Helper to create box
    function createBox(w, h, d, mat, x, y, z) {
        const geo = new THREE.BoxGeometry(w, h, d);
        const mesh = new THREE.Mesh(geo, mat);
        mesh.position.set(x, y, z);
        mesh.castShadow = true;
        return mesh;
    }

    // 1. Hips (Root of the body movement)
    const hips = new THREE.Group();
    hips.position.set(0, 1.0, 0); // Y position of hips
    characterGroup.add(hips);

    // Pelvis visual
    const pelvisMesh = createBox(0.35, 0.2, 0.2, pantsMat, 0, 0, 0);
    hips.add(pelvisMesh);

    // 2. Spine / Torso
    const spine = new THREE.Group();
    spine.position.set(0, 0.1, 0); // Top of hips
    hips.add(spine);

    // Torso visual
    const torsoMesh = createBox(0.4, 0.6, 0.25, shirtMat, 0, 0.3, 0);
    spine.add(torsoMesh);

    // 3. Head
    const head = new THREE.Group();
    head.position.set(0, 0.6, 0); // Top of torso
    spine.add(head);

    const headMesh = createBox(0.25, 0.3, 0.25, skinMat, 0, 0.15, 0);
    head.add(headMesh);

    // 4. Arms
    // Shoulder pivot
    const shoulderL = new THREE.Group(); shoulderL.position.set(0.25, 0.5, 0); spine.add(shoulderL);
    const shoulderR = new THREE.Group(); shoulderR.position.set(-0.25, 0.5, 0); spine.add(shoulderR);

    // Upper Arm
    const upperArmL = new THREE.Group(); upperArmL.position.set(0, 0, 0); shoulderL.add(upperArmL);
    const upperArmR = new THREE.Group(); upperArmR.position.set(0, 0, 0); shoulderR.add(upperArmR);

    const uArmMesh = createBox(0.1, 0.35, 0.1, shirtMat, 0, -0.175, 0);
    upperArmL.add(uArmMesh.clone());
    upperArmR.add(uArmMesh.clone());

    // Elbow pivot
    const elbowL = new THREE.Group(); elbowL.position.set(0, -0.35, 0); upperArmL.add(elbowL);
    const elbowR = new THREE.Group(); elbowR.position.set(0, -0.35, 0); upperArmR.add(elbowR);

    // Lower Arm
    const lowerArmL = new THREE.Group(); lowerArmL.position.set(0, 0, 0); elbowL.add(lowerArmL);
    const lowerArmR = new THREE.Group(); lowerArmR.position.set(0, 0, 0); elbowR.add(lowerArmR);

    const lArmMesh = createBox(0.08, 0.3, 0.08, skinMat, 0, -0.15, 0);
    lowerArmL.add(lArmMesh.clone());
    lowerArmR.add(lArmMesh.clone());

    // 5. Legs
    // Hip pivot
    const hipJointL = new THREE.Group(); hipJointL.position.set(0.12, -0.1, 0); hips.add(hipJointL);
    const hipJointR = new THREE.Group(); hipJointR.position.set(-0.12, -0.1, 0); hips.add(hipJointR);

    // Upper Leg
    const upperLegL = new THREE.Group(); upperLegL.position.set(0, 0, 0); hipJointL.add(upperLegL);
    const upperLegR = new THREE.Group(); upperLegR.position.set(0, 0, 0); hipJointR.add(upperLegR);

    const uLegMesh = createBox(0.15, 0.45, 0.15, pantsMat, 0, -0.225, 0);
    upperLegL.add(uLegMesh.clone());
    upperLegR.add(uLegMesh.clone());

    // Knee pivot
    const kneeL = new THREE.Group(); kneeL.position.set(0, -0.45, 0); upperLegL.add(kneeL);
    const kneeR = new THREE.Group(); kneeR.position.set(0, -0.45, 0); upperLegR.add(kneeR);

    // Lower Leg
    const lowerLegL = new THREE.Group(); lowerLegL.position.set(0, 0, 0); kneeL.add(lowerLegL);
    const lowerLegR = new THREE.Group(); lowerLegR.position.set(0, 0, 0); kneeR.add(lowerLegR);

    const lLegMesh = createBox(0.12, 0.45, 0.12, pantsMat, 0, -0.225, 0);
    lowerLegL.add(lLegMesh.clone());
    lowerLegR.add(lLegMesh.clone());

    // Foot pivot
    const footL = new THREE.Group(); footL.position.set(0, -0.45, 0); lowerLegL.add(footL);
    const footR = new THREE.Group(); footR.position.set(0, -0.45, 0); lowerLegR.add(footR);

    const footMesh = createBox(0.12, 0.08, 0.2, shoeMat, 0, 0, 0.05);
    footL.add(footMesh.clone());
    footR.add(footMesh.clone());

    // --- Environment ---

    // Treadmill Base
    const treadmillGroup = new THREE.Group();
    scene.add(treadmillGroup);

    const beltGeo = new THREE.BoxGeometry(0.8, 0.2, 3);
    const beltMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.8 });
    const belt = new THREE.Mesh(beltGeo, beltMat);
    belt.position.y = -0.1;
    treadmillGroup.add(belt);

    // Side rails
    const railGeo = new THREE.BoxGeometry(0.1, 0.8, 3);
    const railMat = new THREE.MeshStandardMaterial({ color: 0x555555 });
    const railL = new THREE.Mesh(railGeo, railMat);
    railL.position.set(-0.45, 0.3, 0);
    treadmillGroup.add(railL);
    const railR = new THREE.Mesh(railGeo, railMat);
    railR.position.set(0.45, 0.3, 0);
    treadmillGroup.add(railR);

    // Floor
    const floorGeo = new THREE.PlaneGeometry(100, 100);
    const floorMat = new THREE.MeshStandardMaterial({ color: 0x1a1a1a, roughness: 0.5 });
    const floor = new THREE.Mesh(floorGeo, floorMat);
    floor.rotation.x = -Math.PI / 2;
    floor.receiveShadow = true;
    scene.add(floor);

    // --- Animation Logic ---

    const clock = new THREE.Clock();

    function easeInOut(t) {
        return t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
    }

    function animate() {
        requestAnimationFrame(animate);

        const elapsedTime = clock.getElapsedTime();
        const cycleTime = elapsedTime % CYCLE_DURATION;

        // Determine Phase
        let phase = 'STILL';
        let phaseTime = 0; // Time within the current phase (0 to 1)

        if (cycleTime < PHASE_STILL) {
            phase = 'STILL';
            phaseTime = cycleTime / PHASE_STILL;
        } else if (cycleTime < PHASE_STILL + PHASE_WALK) {
            phase = 'WALK';
            phaseTime = (cycleTime - PHASE_STILL) / PHASE_WALK;
        } else {
            phase = 'RUN';
            phaseTime = (cycleTime - PHASE_STILL - PHASE_WALK) / PHASE_RUN;
        }

        // --- State Interpolation ---

        let legSwing = 0;
        let armSwing = 0;
        let kneeBend = 0;
        let elbowBend = 0;
        let torsoLean = 0;
        let hipBob = 0;
        let speedMult = 0;
        let beltSpeed = 0;

        // Default (Still)
        const t = phaseTime;

        if (phase === 'STILL') {
            // Smooth transition to still
            // If just starting still, we reset. If ending still, we prepare.
            // For simplicity in this loop, we snap to 0 for still, 
            // but let's add a tiny ease-in for the first frame if coming from run
            legSwing = 0; armSwing = 0; kneeBend = 0; elbowBend = 0; torsoLean = 0; hipBob = 0;
        } 
        else if (phase === 'WALK') {
            speedMult = 4.0; // Walking frequency
            legSwing = 0.5; // Radians
            armSwing = 0.4;
            kneeBend = 0.3;
            elbowBend = 0.2;
            torsoLean = 0.05; // Slight forward
            hipBob = 0.03;
            beltSpeed = 0.5;
        } 
        else if (phase === 'RUN') {
            speedMult = 8.0; // Running frequency
            legSwing = 1.0; // Larger swing
            armSwing = 0.8;
            kneeBend = 0.8; // More knee lift
            elbowBend = 0.6; // Bent elbows
            torsoLean = 0.2; // Lean forward
            hipBob = 0.08; // More bounce
            beltSpeed = 1.5;
        }

        // Apply Transitions (Smooth entry/exit of phase)
        // We use a simple ease at start and end of phase
        const ease = Math.min(t * 2, (1-t) * 2); // Simple ramp up/down
        const transitionFactor = Math.min(1, Math.min(t * 4, (1 - t) * 4)); // 0 to 1 over 25% of phase

        // If transitioning from Still to Move, we need to ramp up.
        // Since the cycle is discrete, let's just apply the factor to the values calculated above
        // to make it look natural.

        // Special handling for Still -> Walk/Run transition
        if (phase !== 'STILL') {
            legSwing *= transitionFactor;
            armSwing *= transitionFactor;
            kneeBend *= transitionFactor;
            elbowBend *= transitionFactor;
            torsoLean *= transitionFactor;
            hipBob *= transitionFactor;
            beltSpeed *= transitionFactor;
        }

        // --- Calculate Angles ---
        const walkCycle = elapsedTime * speedMult;

        // Legs
        // Left leg leads, Right leg lags
        const lLegAngle = Math.sin(walkCycle) * legSwing;
        const rLegAngle = Math.sin(walkCycle + Math.PI) * legSwing;

        hipJointL.rotation.x = lLegAngle;
        hipJointR.rotation.x = rLegAngle;

        // Knee (Bends when leg goes back)
        // Simple logic: if angle is negative (back), bend knee.
        const lKnee = (lLegAngle < 0) ? lLegAngle * 0.8 + kneeBend : 0; // Simplified bend
        const rKnee = (rLegAngle < 0) ? rLegAngle * 0.8 + kneeBend : 0;

        // Better Knee logic: Knee bends during swing phase (forward) slightly, and extends in stance.
        // For low poly style: Knee bends when leg is back.
        kneeL.rotation.x = Math.max(0, -lLegAngle * 0.5) * (kneeBend > 0.1 ? 1 : 0.1);
        kneeR.rotation.x = Math.max(0, -rLegAngle * 0.5) * (kneeBend > 0.1 ? 1 : 0.1);

        // Arms (Opposite to legs)
        const lArmAngle = Math.sin(walkCycle + Math.PI) * armSwing;
        const rArmAngle = Math.sin(walkCycle) * armSwing;

        shoulderL.rotation.x = lArmAngle;
        shoulderR.rotation.x = rArmAngle;

        // Elbows (Bend slightly)
        elbowL.rotation.x = -Math.abs(lArmAngle) * 0.5 * (elbowBend > 0.1 ? 1 : 0.1);
        elbowR.rotation.x = -Math.abs(rArmAngle) * 0.5 * (elbowBend > 0.1 ? 1 : 0.1);

        // Body
        // Torso Lean
        spine.rotation.x = -torsoLean; // Negative to lean forward (z+)

        // Hip Bob (Vertical movement)
        // Bob twice per step cycle
        const bob = Math.abs(Math.sin(walkCycle)) * hipBob;
        hips.position.y = 1.0 + bob;

        // Belt Rotation (Visual trick)
        // We can't easily texture animate without a texture, but we can rotate the belt mesh slightly
        // or move the floor texture. Since we have no texture, let's just vibrate the belt slightly
        // or rely on the character movement to imply speed.
        // Actually, let's rotate the belt mesh around Y axis to simulate movement? No, it's a box.
        // Let's just leave the belt static visually, the character movement is enough.
        // OR: Add some particles. Let's stick to the prompt requirements.

        renderer.render(scene, camera);
    }

    // Handle Resize
    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });

    animate();

</script>
</body>
</html>
```
